public class JStringEqual2 {
	public static void main(String[] args) {
		//Paso 1: Definir las cadenas
		String str1 = "HOLA MUNDO!";
		String str2 = "hoxa mundo!";
		//Paso 2: Modificar la cadena "hoxa mundo!" para que coincida (ignorando mayusculas/minusculas) con la cadena "HOLA MUNDO!"
